import React, { useState } from 'react';
import { Steps } from 'primereact/steps';

export default function Template() {
    const [activeIndex, setActiveIndex] = useState(0);

    const itemRenderer = (item, itemIndex) => {
        const isActiveItem = activeIndex === itemIndex;
        const backgroundColor = isActiveItem ? 'var(--uls-primary-color)' : 'var(--layer3-bg)';
        const textColor = isActiveItem ? 'var(--static-white)' : 'var(--secondary-text-color)';

        return (
            <span
                className="fxb fhc fvc bdr1 bdr-primary bdr1 h32 w32 rds-circle z-0 pointer"
                style={{ backgroundColor: backgroundColor, color: textColor, marginTop: '-24px' }}
                onClick={() => setActiveIndex(itemIndex)}
            >
                <i className={`${item.icon} font-size14`} />
            </span>
        );
    };

    const items = [
        {
            icon: 'pi pi-user',
            template: (item) => itemRenderer(item, 0)
        },
        {
            icon: 'pi pi-calendar',
            template: (item) => itemRenderer(item, 1)
        },
        {
            icon: 'pi pi-check',
            template: (item) => itemRenderer(item, 2)
        }
    ];

    return (
        <>
            <Steps model={items} activeIndex={activeIndex} readOnly={false} className="mg2 pdt4" />
        </>
    )

}